from fractions import Fraction as F
from math import factorial,comb
import json
checks=[]
def record(name,ok,scope,count):
 if not ok: raise ValueError(name)
 checks.append(dict(name=name,passed=True,scope=scope,cases=count))
def matmul(a,b):
 return [[sum(x*y for x,y in zip(row,col)) for col in zip(*b)] for row in a]
A=[[F(0),F(0),-F(4,3)],[F(0),F(0),F(-2)],[F(1),F(2),F(0)]]
G=[[F(3,4),F(0),F(0)],[F(0),F(1),F(0)],[F(0),F(0),F(1)]]
atg=matmul(list(map(list,zip(*A))),G); ga=matmul(G,A)
record('Stationary tangent metric skew identity',all(atg[i][j]+ga[i][j]==0 for i in range(3) for j in range(3)),'Exact A^T G+GA=0 for the one-mode secular falsifier.',9)
record('Rational Z fraction below one quarter',F(67743204500,274510827927)<F(1,4),'Arithmetic endpoint only; does not independently prove the quadrature majorant.',1)
for d in range(41):
 vals=[F(a*a+b*b)+F(3,2)*c*c+F(1,2)*a*b+F(3,2)*c*(a+b)+2*a+2*b+3*c for a in range(d+1) for b in range(d-a+1) for c in [d-a-b]]
 if min(vals)!=F(5,8)*d*d+2*d+F(3,8)*(d%2): raise ValueError('shell '+str(d))
record('Two-square exact shell minimum',True,'Finite enumeration degrees 0..40; analytic all-degree proof remains in source and manuscript.',41)
def moment(n):
 if n%2: return F(0)
 k=n//2
 return F(comb(2*k,k),k+1)/4**k
record('Haar moment recurrence at zero coupling',all(n*(moment(n-1) if n else 0)-(n+3)*moment(n+1)==0 for n in range(25)),'Exact Catalan moments through recurrence n=24.',25)
for N in [2,3,4,8,17,100]:
 c=F(1,3); delta=F(1,4)
 B=[[F(int(i==j)) for j in range(N)] for i in range(N)]
 for i in [0,1]:
  for j in [0,1]:B[i][j]=F(1,2)
 P=[[(1-c)*B[i][j]+c/N for j in range(N)] for i in range(N)]
 Q=[row[:] for row in P]
 Q[0][0]+=delta/2;Q[1][1]+=delta/2;Q[0][1]-=delta/2;Q[1][0]-=delta/2
 if not all(sum(row)==1 and min(row)>0 for row in Q):raise ValueError('Markov')
 v=[F(1),F(-1)]+[F(0)]*(N-2)
 if any(sum((Q[i][j]-P[i][j])*v[j] for j in range(N))!=delta*v[i] for i in range(N)):raise ValueError('eigenvector')
 if sum(abs(Q[i][j]-P[i][j]) for i in range(N) for j in range(N))/N!=2*delta/N:raise ValueError('L1')
record('Positive Markov norm counterexample',True,'Row sums/positivity, exact nonzero eigenvector and density-kernel product L1; PSD/full norm proven by rank-one decomposition.',6)
for h,k,kap,lam,rho,pp,pl,Q in [(F(1,3),F(-2,5),F(3,7),F(1,11),F(7,4),F(2,9),F(-3,8),F(4,13)),(F(0),F(2),F(1),F(0),F(3),F(2),F(-1),F(5))]:
 hd=(lam-kap*pl-3*h*h)/2
 kd=lam-kap*pp-h*h-k*k-h*k-hd
 rd=Q-2*h*(rho+pp)-k*(rho+pl)
 C=h*h+2*h*k-kap*rho-lam
 cd=2*h*hd+2*hd*k+2*h*kd-kap*rd
 if cd!=-(2*h+k)*C-kap*Q:raise ValueError('constraint')
record('Bianchi constraint signs',True,'Exact rational off-constraint probes including nonzero energy residual; not symbolic proof.',2)
e=F(114,5)**101/factorial(101)
record('R12 action and state arithmetic',F(3,10)**4/factorial(4)==F(27,80000) and F(1,2)**5/factorial(5)==F(1,3840) and 2*e+e*e<F(1,10**22),'Rational action-tail and Taylor-product endpoint checks; no 20-dimensional state replay.',3)
eta=F(1,10)
record('Spurious truncated concurrence',2*eta*eta/(1+2*eta*eta)==F(1,51),'Normalized first-order product-state truncation only.',1)
print(json.dumps({'checks':checks,'passed':len(checks),'all_passed':True},sort_keys=True))
